const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
 folder:'M3 7h6l2 2h10v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Zm0 0V5h7l2 2',canvas:'M4 4h16v16H4zM4 10h16M10 4v16',layers:'m12 3 10 5-10 5L2 8Zm-9 9 9 5 9-5M3 16l9 5 9-5',help:'M9.1 9a3 3 0 0 1 5.8 1c0 2-3 2-3 4m0 3h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',history:'M3 11a9 9 0 1 1 2 7M3 4v7h7m2-5v6l4 2',play:'m9 5 11 7-11 7z',pause:'M8 5v14M16 5v14',export:'M12 15V3m-4 4 4-4 4 4M4 13v7h16v-7',chevrons:'m8 9 4-4 4 4m-8 6 4 4 4-4',plus:'M12 4v16M4 12h16','arrow-up-right':'M5 19 19 5M5 5h14v14',check:'m5 12 4 4L19 6',lock:'M6 10h12v11H6zm3 0V6a3 3 0 0 1 6 0v4m-3 5v2',sparkles:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Zm7-1v4m-2-2h4',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',filter:'M3 5h18l-7 8v6l-4 2v-8Z',search:'M21 21l-5-5m2-6a7 7 0 1 1-14 0 7 7 0 0 1 14 0',more:'M5 12h.01M12 12h.01M19 12h.01',camera:'M3 7h4l2-3h6l2 3h4v13H3zm13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',warning:'m12 3 10 18H2Zm0 6v5m0 3h.01',refresh:'M20 7a9 9 0 0 0-15-2L2 8m0-6v6h6m-4 9a9 9 0 0 0 15 2l3-3m0 6v-6h-6',eye:'M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',close:'m6 6 12 12M6 18 18 6',expand:'M3 9V3h6m6 0h6v6m0 6v6h-6M9 21H3v-6',volume:'M11 4 5 9H2v6h3l6 5Zm4 4a5 5 0 0 1 0 8m3-11a9 9 0 0 1 0 14',film:'M3 3h18v18H3zM7 3v18M17 3v18M3 8h4m-4 8h4m10-8h4m-4 8h4',music:'M9 18V5l12-2v13m-12-7 12-2M9 18a3 3 0 1 1-6 0 3 3 0 0 1 6 0m12-2a3 3 0 1 1-6 0 3 3 0 0 1 6 0',rewind:'m12 5-9 7 9 7Zm9 0-9 7 9 7Z',undo:'M4 10h10a6 6 0 0 1 0 12M4 10l5-5M4 10l5 5',file:'M5 2h9l5 5v15H5Zm9 0v6h5M9 13h6m-6 4h6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',edit:'m16 3 5 5-12 12-6 1 1-6Zm-2 2 5 5',arrow:'M4 12h16m-6-6 6 6-6 6',bookmark:'M6 3h12v19l-6-4-6 4z',settings:'M4 7h16M4 17h16M8 3v8m8 2v8',heart:'M20 4q-5-3-8 3-3-6-8-3-6 5 8 17Q26 9 20 4',voice:'M9 3h6v12H9zm-4 8v2a7 7 0 0 0 14 0v-2m-7 9v3',cloud:'M6 18h13a4 4 0 0 0 0-8 7 7 0 0 0-13-1 5 5 0 0 0 0 9',move:'M12 2v20M2 12h20m-14-6 4-4 4 4m-8 12 4 4 4-4M6 8l-4 4 4 4m12-8 4 4-4 4',cut:'m9 9 11 11M9 15 20 4M10 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0m0 10a4 4 0 1 1-8 0 4 4 0 0 1 8 0',sort:'M8 3v18m-4-4 4 4 4-4m4-14v18m-4-14 4-4 4 4'
};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.sparkles}"/></svg>`;}
function hydrateIcons(root=document){$$('[data-icon]',root).forEach(n=>n.innerHTML=icon(n.dataset.icon));}
const initialShots = [
{title:'雨中的旧书店',dialogue:'那家书店，还在原来的地方。',speaker:'旁白',duration:5,template:'横向摇移',channel:'stable',review:false,version:1},
{title:'熟悉的身影',dialogue:'七年了，你还记得我吗？',speaker:'林夏',duration:4,template:'缓慢推进',channel:'stable',review:false,version:2},
{title:'门后的重逢',dialogue:'我以为，你不会再来了。',speaker:'陈序',duration:5,template:'缓慢推进',channel:'stable',review:false,version:1},
{title:'未寄出的信',dialogue:'有些话，写了很久也没寄出去。',speaker:'林夏',duration:5,template:'视差景深',channel:'stable',review:true,version:2},
{title:'关于那场雨',dialogue:'那天的雨，好像一直没有停。',speaker:'陈序',duration:4,template:'固定镜头',channel:'stable',review:false,version:1},
{title:'伸出的手',dialogue:'这一次，一起走吧。',speaker:'陈序',duration:5,template:'缓慢拉远',channel:'enhanced',review:false,version:1,hasEnhanced:true},
{title:'同一把伞下',dialogue:'好。',speaker:'林夏',duration:5,template:'视差景深',channel:'stable',review:false,version:1},
{title:'雨停的城市',dialogue:'原来雨停之后，世界是这样的。',speaker:'旁白',duration:5,template:'横向摇移',channel:'stable',review:false,version:1},
{title:'微光落在眼里',dialogue:'下次，换我等你。',speaker:'林夏',duration:4,template:'缓慢推进',channel:'stable',review:true,version:1},
{title:'故事还在继续',dialogue:'有些重逢，是故事重新开始。',speaker:'旁白',duration:6,template:'缓慢拉远',channel:'stable',review:false,version:1}
];
const defaultSettings=()=>({blink:true,lipsync:true,parallax:false,rain:false,safe:false,intensity:24});
initialShots.forEach((s,i)=>{s.artIndex=i;s.reviewType=i===3?'subtitle':i===8?'identity':null;s.settings=defaultSettings();s.subtitle=true;s.revisions=[];});
const defaultState=()=>({page:'motion',selected:1,filter:'all',inspectorTab:'motion',assetTab:'characters',view:'grid',comicView:'grid',spend:4.82,budget:15,approved:false,locked:true,focusMode:false,exportOptions:{type:'video',fps:24,subtitles:'zh'},subtitle:true,shots:structuredClone(initialShots),settings:{blink:true,lipsync:true,parallax:false,rain:false,safe:false,intensity:24},events:[{time:'14:32',title:'条漫分格已确认',detail:'10 个分格 · 角色与画风资产已锁定'},{time:'14:35',title:'稳定动画已生成',detail:'10 个镜头 · 运镜、字幕与配音完成'},{time:'14:39',title:'镜头 06 采用增强版本',detail:'Kling 3.0 · 5 秒 · $0.45'},{time:'14:41',title:'发现 2 项待确认问题',detail:'镜头 04 字幕安全区 · 镜头 09 角色一致性'}]});
const studioParams=new URLSearchParams(location.search),studioProjectId=studioParams.get('project')||'rain',studioChapterId=studioParams.get('chapter')||'ch1';
const studioKey=studioProjectId==='rain'&&studioChapterId==='ch1'?'framein-m0-v1':`framein-m0-${studioProjectId}-${studioChapterId}`;
let siteContext;try{siteContext=JSON.parse(localStorage.getItem('framein-site-v1'));}catch{}
const studioProject=siteContext?.projects?.find(p=>p.id===studioProjectId),studioChapter=studioProject?.chapters.find(c=>c.id===studioChapterId);
let state=defaultState();try{const local=JSON.parse(localStorage.getItem(studioKey));if(local?.shots?.length>=8){state={...state,...local,page:location.hash.slice(1)||'motion',filter:'all',view:'grid',inspectorTab:'motion'};}else if(studioProject?.text){state.script=studioProject.text;}}catch{}
if(siteContext?.prefs?.budget)state.budget=siteContext.prefs.budget;
const pages=['script','assets','comic','motion','export'];state.page=pages.includes(location.hash.slice(1))?location.hash.slice(1):state.page;if(!pages.includes(state.page))state.page='motion';
state.shots.forEach((s,i)=>{s.artIndex??=i%10;s.reviewType??=s.artIndex===3?'subtitle':s.artIndex===8?'identity':null;s.settings={...defaultSettings(),...(s.settings||state.settings||{})};s.subtitle??=state.subtitle??true;s.revisions??=[];});
state.selected=Math.max(0,Math.min(state.shots.length-1,Number(state.selected)||0));
state.exportOptions={type:'video',fps:24,subtitles:'zh',...state.exportOptions};
state.focusMode??=false;
let playing=false,elapsed=0,playTimer=null,modalTimer=null,modalReturnFocus=null;
const artUrls=Array.from({length:10},(_,i)=>Art.url(i));
const artForShot=i=>artUrls[(state.shots[i]?.artIndex??i)%10];
const image=(i,cls='',alt='')=>`<img class="${cls}" src="${alt?artUrls[(i+10)%10]:artForShot(i)}" alt="${esc(alt||state.shots[i]?.title||'示例分镜')}" draggable="false">`;
const shot=()=>state.shots[state.selected];
const total=()=>state.shots.reduce((n,s)=>n+Number(s.duration),0);
const money=n=>'$'+Number(n).toFixed(2);
const time=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(Math.floor(n%60)).padStart(2,'0')}`;
const countReview=()=>state.shots.filter(s=>s.review).length;
function save(){try{localStorage.setItem(studioKey,JSON.stringify(state));$('#save-status').innerHTML='<b></b> 已保存到本机';}catch{$('#save-status').textContent='本机存储不可用';}updateBudget();}
function log(title,detail){state.events.push({time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),title,detail});save();}
function toast(message,type='check'){const el=document.createElement('div');el.className='toast';el.innerHTML=icon(type)+`<span>${esc(message)}</span>`;$('#toast-stack').append(el);setTimeout(()=>el.remove(),4200);}
function updateBudget(){$('#side-spend').innerHTML=`${money(state.spend)} <small>/ ${money(state.budget)}</small>`;$('#side-meter').style.width=`${Math.min(100,state.spend/state.budget*100)}%`;}
function navigate(page){if(!pages.includes(page))return;stopPlayback();state.page=page;state.filter='all';state.approved=false;history.replaceState(null,'','#'+page);closeModal();render();save();}
function render(){
 $('.chapter small').textContent=`${state.shots.length} 分格 · ${total()} 秒`;
 $('.app').classList.toggle('no-timeline',!['motion','comic'].includes(state.page));
 $('.app').classList.toggle('focus-mode',state.focusMode);
 $$('.stepbar [data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===state.page);b.setAttribute('aria-current',b.dataset.page===state.page?'step':'false');});
 $$('.rail-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page||b.dataset.page==='motion'&&['script','comic','export'].includes(state.page)));
 renderSidebar();
 const content={motion:renderMotion,comic:renderComic,assets:renderAssets,script:renderScript,export:renderExport};$('#workspace').innerHTML=content[state.page]();
 renderTimeline();updateBudget();hydrateIcons();syncPreview();window.dispatchEvent(new Event('framein:studio-render'));
}
function syncPreview(){
 const frame=$('#inspector-preview');
 if(frame){frame.dataset.motion=shot().template;frame.style.setProperty('--motion-strength',String(1+shot().settings.intensity/180));const subtitle=$('.preview-subtitle',frame);if(subtitle)subtitle.style.bottom=shot().subtitleLift?'32px':'';}
 const heading=$('.inspector-heading');
 if(heading&&!$('.mobile-inspector-close',heading)){const button=document.createElement('button');button.className='icon-btn mobile-inspector-close';button.dataset.action='close-inspector';button.setAttribute('aria-label','关闭镜头属性');button.innerHTML=icon('close');heading.append(button);}
 const gap=$('[data-field="comic-gap"]');if(gap){gap.value=state.comicGap??16;$('#gap-label').textContent=gap.value+' px';$('#long-comic').style.gap=gap.value+'px';}
 const width=$('[aria-label="长图宽度"]');if(width)width.value=(state.comicWidth||1080)+' px';
 $$('[data-export-field]').forEach(el=>el.value=String(state.exportOptions[el.dataset.exportField]));
}
function renderSidebar(){
 $$('.asset-tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.assetTab===state.assetTab);b.setAttribute('aria-selected',b.dataset.assetTab===state.assetTab);});
 const list=state.assetTab==='characters'?[{name:'林夏',sub:'角色 v2 · 6 个参考',img:1},{name:'陈序',sub:'角色 v1 · 4 个参考',img:2}]:state.assetTab==='scenes'?[{name:'慢日子书店',sub:'场景 v1 · 室内 / 室外',img:0},{name:'雨后的街道',sub:'场景 v1 · 黄昏',img:7}]:[{name:'雨日手绘',sub:'画风 v1 · 柔和水彩',img:8}];
 $('#sidebar-assets').innerHTML=list.map(a=>`<button class="asset-mini" data-action="asset-detail" data-name="${a.name}" data-img="${a.img}">${image(a.img,'',a.name)}<span><strong>${a.name}</strong><small>${a.sub}</small></span>${icon('lock')}</button>`).join('');
 $('.lock-label').textContent=state.locked?'资产已锁定':'资产待锁定';
}
function boardHeader(comic=false){return `<div class="board-header"><div><span class="eyebrow">CHAPTER 01 / ${comic?'WEBTOON':'MOTION COMIC'}</span><h1>${comic?'条漫创作':'动态漫画布'} <span class="title-dot">/</span> <span style="color:#a4a1ae;font-size:.67em;font-weight:400">重逢的第七天</span></h1><p>${comic?'让每一格画面，都讲述同一个故事。':'从静止的画面，到流动的故事。'} <span style="color:#625f6c">·</span> ${state.shots.length} ${comic?'分格':'镜头'} <span style="color:#625f6c">·</span> ${total()} 秒</p></div><div class="header-actions"><button class="btn small focus-toggle ${state.focusMode?'active':''}" data-action="toggle-focus" aria-pressed="${state.focusMode}" title="${state.focusMode?'恢复项目与资产栏':'收起资产栏，展开画布'}">${icon(state.focusMode?'grid':'expand')} ${state.focusMode?'退出专注':'专注画布'}</button>${comic?`<div class="segmented"><button class="${state.comicView==='grid'?'active':''}" data-comic-view="grid">${icon('grid')} 分格</button><button class="${state.comicView==='long'?'active':''}" data-comic-view="long">${icon('list')} 长图</button></div>`:`<div class="segmented"><button class="${state.view==='grid'?'active':''}" data-view="grid" title="镜头卡视图">${icon('grid')}</button><button class="${state.view==='list'?'active':''}" data-view="list" title="分镜列表视图">${icon('list')}</button></div>`}<button class="btn small" data-action="${comic?'batch-panels':'batch-stable'}">${icon('sparkles')} ${comic?'批量生成':'生成稳定初稿'}</button></div></div>`;}
function filterBar(){return `<div class="board-toolbar"><div class="filters" role="tablist" aria-label="镜头筛选"><button class="${state.filter==='all'?'active':''}" data-filter="all">全部 <small>${state.shots.length}</small></button><button class="${state.filter==='review'?'active':''}" data-filter="review">待确认 <small>${countReview()}</small></button><button class="${state.filter==='enhanced'?'active':''}" data-filter="enhanced">增强 <small>${state.shots.filter(s=>s.channel==='enhanced').length}</small></button></div><div class="toolbar-right"><button class="focus-budget" data-action="budget">预算 ${money(state.spend)} <small>/ ${money(state.budget)}</small></button><button class="icon-btn" data-action="search" title="搜索镜头">${icon('search')}</button><button class="icon-btn" data-action="sort" title="调整镜头顺序">${icon('sort')}</button><button class="icon-btn" data-action="guide" title="查看交互导览">${icon('help')}</button></div></div>`;}
function renderCard(s,i,comic=false){return `<article class="shot-card ${state.selected===i?'selected':''} ${s.channel==='enhanced'?'enhanced':''}" tabindex="0" role="button" aria-label="选择镜头 ${String(i+1).padStart(2,'0')} ${esc(s.title)}" aria-pressed="${state.selected===i}" data-shot="${i}"><div class="shot-image">${image(i)}<span class="shot-index">${String(i+1).padStart(2,'0')}</span><span class="shot-check">✓</span><span class="duration">${comic?'v'+s.version:time(s.duration)}</span></div><div class="shot-info"><div class="shot-name"><strong>${esc(s.title)}</strong><span>⋮</span></div><p class="shot-dialogue">${esc(s.speaker)}：${esc(s.dialogue)}</p><div class="shot-meta"><span>${icon(comic?'bookmark':'camera')}${comic?(i%2?'林夏':'陈序')+' · 画风已绑定':s.template}</span><span>${comic?'已采用 v'+s.version:(s.channel==='enhanced'?'Kling 3.0':'稳定动画')}</span></div></div><div class="shot-status"><span class="badge ${s.review?'warning':s.channel==='enhanced'?'':'success'}">${s.review?'◈ 待确认':s.channel==='enhanced'?'✧ 增强已采用':'✓ '+(comic?'已确认':'可预览')}</span><span>${comic?'Nano Banana 2':s.channel==='enhanced'?'$0.45':'无额外费用'}</span></div></article>`;}
function renderMotion(){
 const filtered=state.shots.map((s,i)=>({s,i})).filter(({s})=>state.filter==='all'||state.filter==='review'&&s.review||state.filter==='enhanced'&&s.channel==='enhanced');
 return `<div class="board">${boardHeader()}${filterBar()}<div class="board-scroll"><div class="notice">${icon('sparkles')}<span><strong style="font-weight:500;color:#c9b9d8">稳定动画已就绪</strong> · ${state.shots.length} 个镜头都有可交付底稿，关键动作可以单独增强。</span><button class="text-link" data-action="enhance">增强选中镜头 ↗</button></div><div class="shot-grid" style="${state.view==='list'?'grid-template-columns:1fr;':''}">${filtered.map(({s,i})=>state.view==='list'?renderListCard(s,i):renderCard(s,i)).join('')}${filtered.length?`<button class="add-shot" data-action="add-shot">${icon('plus')}<span>添加镜头</span><small class="tiny">从已确认分格中选择</small></button>`:`<div class="empty-state">${icon('check')}<h3>这里暂时没有镜头</h3><p>${state.filter==='review'?'所有异常都已确认，可以继续导出了。':'试试生成并采用一个关键动作候选。'}</p><button class="btn" data-filter="all">查看全部镜头</button></div>`}</div><p class="local-note">${icon('lock').replace('class="icon ','class="icon ').replace('<svg','<svg style="display:inline-block;width:10px;height:10px;vertical-align:middle"')} 角色、场景与画风沿用条漫资产 · 仅重做发生变化的镜头</p></div></div>${renderInspector()}`;
}
function renderListCard(s,i){return `<button class="shot-card ${state.selected===i?'selected':''}" data-shot="${i}" style="display:flex;align-items:center;text-align:left"><div class="shot-image" style="width:150px;flex-shrink:0">${image(i)}<span class="shot-index">${String(i+1).padStart(2,'0')}</span><span class="duration">${time(s.duration)}</span></div><div class="shot-info" style="flex:1"><div class="shot-name"><strong>${esc(s.title)}</strong><span class="badge ${s.review?'warning':'success'}">${s.review?'待确认':'可预览'}</span></div><p class="shot-dialogue">${esc(s.dialogue)}</p><div class="shot-meta"><span>${s.template}</span><span>${s.channel==='enhanced'?'生成式增强':'稳定动画'}</span></div></div></button>`;}
function renderInspector(comic=false){const s=shot();return `<aside class="inspector" aria-label="选中镜头属性"><div class="inspector-heading"><strong>${comic?'分格':'镜头'} ${String(state.selected+1).padStart(2,'0')} <span>· ${esc(s.title)}</span></strong><button class="icon-btn" data-action="${comic?'edit-panel':'preview-shot'}" title="打开单镜头编辑器">${icon('expand')}</button></div><div class="preview-stage"><span class="preview-ratio">9:16</span><div class="preview-frame ${shot().settings.safe?'show-safe':''} ${shot().settings.rain?'effect-rain':''}" id="inspector-preview">${image(state.selected)}<div class="safe-area"></div><div class="preview-subtitle">${shot().subtitle?esc(s.dialogue):''}</div></div><button class="play-overlay" data-action="toggle-play" aria-label="播放选中镜头">${icon('play')}</button><button class="preview-fullscreen icon-btn" data-action="safe-area" title="切换字幕安全区">${icon('expand')}</button></div><div class="preview-controls"><button class="icon-btn" data-action="previous-shot" title="上一个镜头">${icon('rewind')}</button><span>${time(0)}</span><progress value="0" max="${s.duration}" id="preview-progress"></progress><span>${time(s.duration)}</span><button class="icon-btn" data-action="mute" title="音频状态">${icon('volume')}</button></div><div class="inspector-tabs" role="tablist" aria-label="镜头属性分类">${(comic?['panel','dialogue','versions']:['motion','dialogue','versions']).map(t=>`<button role="tab" aria-selected="${state.inspectorTab===t}" class="${state.inspectorTab===t?'active':''}" data-inspector-tab="${t}">${{panel:'分格',motion:'动画',dialogue:'配音 / 字幕',versions:'版本'}[t]}</button>`).join('')}</div><div class="property-content">${renderProperties(comic)}</div><div class="inspector-bottom"><button class="btn primary full" data-action="${comic?'edit-panel':'edit-shot'}">${icon('edit')} ${comic?'编辑选中分格':'打开单镜头编辑器'}</button></div></aside>`;}
function renderProperties(comic=false){const s=shot();
 if(state.inspectorTab==='versions')return renderVersions();
 if(state.inspectorTab==='dialogue')return `<div><div class="property-label">对白 / 旁白 <small>${esc(s.speaker)}</small></div><textarea id="inspector-dialogue" aria-label="对白内容" data-field="dialogue" style="font-size:10px">${esc(s.dialogue)}</textarea></div><div><div class="property-label">声音资产 <small>ElevenLabs v4</small></div><select aria-label="声音资产" data-field="speaker"><option ${s.speaker==='林夏'?'selected':''}>林夏</option><option ${s.speaker==='陈序'?'selected':''}>陈序</option><option ${s.speaker==='旁白'?'selected':''}>旁白</option></select></div><button class="btn subtle small full" data-action="tts">${icon('voice')} 生成配音预览 <span class="spacer"></span><small>$0.02</small></button><div class="switch-row">显示字幕<button class="switch ${shot().subtitle?'on':''}" role="switch" aria-checked="${shot().subtitle}" aria-label="显示字幕" data-toggle="subtitle"></button></div><div class="switch-row">字幕安全区<button class="switch ${shot().settings.safe?'on':''}" role="switch" aria-checked="${shot().settings.safe}" aria-label="字幕安全区" data-toggle="safe"></button></div><p class="tiny" style="line-height:1.9">文本修改会创建新版本，仅影响当前镜头的字幕与配音预览。</p>`;
 if(comic||state.inspectorTab==='panel')return `<div><div class="property-label">绑定资产 <small>版本已锁定</small></div><div class="chip-list"><span class="badge">${s.speaker==='陈序'?'陈序 v1':'林夏 v2'}</span><span class="badge neutral">${state.selected<7?'慢日子书店':'雨后的街道'}</span><span class="badge neutral">雨日手绘 v1</span></div></div><div><div class="property-label">构图 / 景别</div><select aria-label="分格景别" data-field="composition"><option>中近景 · 角色居中</option><option>远景 · 环境叙事</option><option>特写 · 情绪表达</option></select></div><div><div class="property-label">表情</div><div class="chip-list"><button class="chip active" data-expression="平静">平静</button><button class="chip" data-expression="微笑">微笑</button><button class="chip" data-expression="惊讶">惊讶</button></div></div><p class="tiny" style="line-height:1.9">画面内容在分格编辑器中修改。采用新版本前，会保留当前版本及动态镜头。</p>`;
 return `<div><div class="property-label">动画通道 <small>${s.channel==='stable'?'确定性 · 可编辑':'增强已采用'}</small></div><div class="channel-switch"><button class="channel-button ${s.channel==='stable'?'active':''}" data-action="adopt-stable"><strong>◈ 稳定动画</strong><small>可编辑 · 无额外费用</small></button><button class="channel-button ${s.channel==='enhanced'?'active':''}" data-action="${s.hasEnhanced?'adopt-enhanced':'enhance'}"><strong>✧ 生成式增强</strong><small>${s.hasEnhanced?'候选已就绪':'关键动作 · 按量计费'}</small></button></div></div><div><div class="property-label">运镜模板 <small>${esc(s.template)}</small></div><div class="template-select">${[['固定镜头','·','固定'],['横向摇移','↔','摇移'],['缓慢推进','↗','推进'],['缓慢拉远','↙','拉远'],['视差景深','▱','视差']].map(([t,g,l])=>`<button class="template-tile ${s.template===t?'active':''}" data-template="${t}" title="${t}"><b>${g}</b>${l}</button>`).join('')}</div></div><div><div class="property-label">运动强度 <small id="intensity-label">${shot().settings.intensity}%</small></div><input type="range" min="0" max="60" value="${shot().settings.intensity}" data-field="intensity" aria-label="运动强度"></div><div>${[['blink','眨眼'],['lipsync','口型同步'],['parallax','视差景深'],['rain','环境雨滴']].map(([key,label])=>`<div class="switch-row">${label}<button class="switch ${shot().settings[key]?'on':''}" role="switch" aria-label="${label}" aria-checked="${shot().settings[key]}" data-toggle="${key}"></button></div>`).join('')}</div>${s.review?`<div class="notice" style="margin:0">${icon('warning')}<span>${s.reviewType==='subtitle'?'字幕靠近下方安全区':s.reviewType==='sync'?'分格新版本待同步':'角色表情与资产参考略有差异'}<br><button class="text-link" style="margin:5px 0 0" data-action="review-shot">查看并确认 →</button></span></div>`:''}`;
}
function renderComic(){return `<div class="board">${boardHeader(true)}${state.comicView==='grid'?`${filterBar()}<div class="board-scroll"><div class="notice">${icon('lock')}<span>2 名角色、2 个场景与 1 种画风已锁定。每个分格共享同一组视觉资产。</span><button class="text-link" data-page="assets">查看资产 ↗</button></div><div class="shot-grid">${state.shots.map((s,i)=>renderCard(s,i,true)).join('')}</div></div>`:`<div class="board-scroll"><div class="comic-full"><div class="layout-preview" id="long-comic"><header><h2>${esc(studioProject?.name||'雨停之前')}</h2><p>${esc(studioChapter?.title||'第 01 章 · 重逢的第七天')}</p></header>${state.shots.map((s,i)=>`<div class="webtoon-panel">${image(i)}${i%2?`<div class="speech-bubble">${esc(s.dialogue)}</div>`:''}</div>`).join('')}<p style="text-align:center;font-size:9px;letter-spacing:2px;color:#8e8175;margin-top:15px">TO BE CONTINUED</p></div><aside class="layout-options"><h3 style="font-size:12px;margin-bottom:15px">长图排版</h3><div><div class="property-label">分格间距 <small id="gap-label">16 px</small></div><input type="range" min="4" max="50" value="16" data-field="comic-gap" aria-label="分格间距"></div><div style="margin-top:15px"><div class="property-label">输出宽度</div><select aria-label="长图宽度"><option>1080 px</option><option>800 px</option></select></div><button class="btn primary full" style="margin-top:22px" data-action="export-png">${icon('download')} 导出 PNG</button><p class="tiny" style="line-height:1.9;margin-top:15px">导出本地示例插画长图。图像内容请返回分格卡修改。</p></aside></div></div>`}</div>${state.comicView==='grid'?renderInspector(true):''}`;}
function renderAssets(){return `<div class="page-content"><div class="page-header"><div><span class="eyebrow">CHAPTER 01 / VISUAL ASSETS</span><h1>同一个世界，同一组角色。</h1><p>先定义故事的视觉语言，再让它贯穿每一格画面、每一个镜头。</p></div><button class="btn ${state.locked?'':'primary'}" data-action="lock-assets">${icon(state.locked?'lock':'check')} ${state.locked?'资产已锁定 · v2':'锁定本章资产'}</button></div><section class="asset-section"><div class="asset-section-heading"><h2>主要角色</h2><span>2 / 2 · 引用于 10 个分格</span><span class="spacer"></span><button class="text-link" data-action="asset-reference">＋ 添加参考图</button></div><div class="asset-grid"><article class="asset-card"><div class="asset-image">${image(1,'','林夏角色示意')}<span class="badge">${icon('lock')} v2</span></div><div class="asset-copy"><h3>林夏 <small class="muted">LIN XIA</small></h3><p>26 岁 · 插画师<br>深色长发、红色围巾、米色风衣</p><div class="row"><span class="badge success">6 个参考已确认</span><span class="tiny">6 格引用</span></div><button class="btn full small" data-action="asset-detail" data-name="林夏" data-img="1">查看角色设定 ${icon('arrow-up-right')}</button></div></article><article class="asset-card"><div class="asset-image">${image(2,'','陈序角色示意')}<span class="badge">${icon('lock')} v1</span></div><div class="asset-copy"><h3>陈序 <small class="muted">CHEN XU</small></h3><p>28 岁 · 书店店主<br>棕色短发、灰蓝外套、沉静温柔</p><div class="row"><span class="badge success">4 个参考已确认</span><span class="tiny">5 格引用</span></div><button class="btn full small" data-action="asset-detail" data-name="陈序" data-img="2">查看角色设定 ${icon('arrow-up-right')}</button></div></article><article class="asset-card"><div class="asset-image">${image(8,'','雨日手绘画风示意')}<span class="badge">画风 v1</span></div><div class="asset-copy"><h3>雨日手绘</h3><p>柔和水彩 · 细腻线稿<br>低饱和灰蓝、温暖琥珀光、胶片颗粒</p><div class="row"><span class="badge neutral">全章画风</span><span class="tiny">10 格引用</span></div><button class="btn full small" data-action="asset-detail" data-name="雨日手绘" data-img="8">查看画风约束 ${icon('arrow-up-right')}</button></div></article><button class="add-shot" data-action="asset-reference" style="min-height:250px">${icon('plus')}<span>补充资产参考</span><small>支持 PNG / JPEG</small></button></div></section><section class="asset-section"><div class="asset-section-heading"><h2>场景与声音</h2><span>共享场景，固定角色音色</span></div><div class="asset-grid scenes">${[{name:'慢日子书店',img:0,desc:'街角旧书店 · 室内 / 室外 · 雨天'},{name:'雨后的街道',img:7,desc:'城市街道 · 黄昏 · 雨后微光'}].map(a=>`<article class="asset-card"><div class="asset-image">${image(a.img)}</div><div class="asset-copy"><h3>${a.name}</h3><p>${a.desc}</p><button class="text-link" data-action="asset-detail" data-name="${a.name}" data-img="${a.img}">查看场景参考 →</button></div></article>`).join('')}<article class="asset-card"><div class="asset-copy" style="padding:22px"><h3 style="margin-bottom:18px">角色声音 <small class="muted">ElevenLabs</small></h3><div class="switch-row"><span>林夏 · 温柔清澈</span><button class="icon-btn" data-action="voice-demo" data-name="林夏" title="试听林夏示例">${icon('play')}</button></div><div class="switch-row"><span>陈序 · 低沉沉静</span><button class="icon-btn" data-action="voice-demo" data-name="陈序" title="试听陈序示例">${icon('play')}</button></div><p style="margin-top:10px">固定音色，跨镜头保持一致。</p></div></article></div></section><div class="page-note">${icon('layers')}<span>条漫与动态漫引用同一组资产版本。修改已锁定资产时，会展示影响范围，并保留现有画面。</span><button class="btn small" style="margin-left:auto" data-page="comic">进入条漫创作 ${icon('arrow')}</button></div></div>`;}
function renderScript(){return `<div class="page-content"><div class="page-header"><div><span class="eyebrow">CHAPTER 01 / STORY SCRIPT</span><h1>好故事，是一切的起点。</h1><p>导入完整剧本或已整理的小说片段，确认本章分镜后再开始创作。</p></div><span class="badge success" style="margin-top:8px">✓ 剧本已确认 · 10 个分格</span></div><div class="script-layout"><section class="surface-card"><div class="row between" style="margin-bottom:15px"><h3 style="margin:0">原始剧本</h3><button class="text-link" data-action="import-script">导入 .txt</button></div><textarea class="script-text" aria-label="章节原始剧本" id="script-text">${esc(state.script||`《雨停之前》 第 01 章：重逢的第七天\n\n场景一 · 慢日子书店 · 雨天\n\n七年后，林夏重新走进那条熟悉的小巷。雨落在旧书店的招牌上，像过去从未离开。\n\n林夏（望着橱窗）：七年了，你还记得我吗？\n陈序（从书架后抬头）：我以为，你不会再来了。\n\n她从风衣口袋里拿出一封泛黄的信。那些未曾说出口的话，终于有了去处。\n\n林夏：有些话，写了很久也没寄出去。\n陈序：那天的雨，好像一直没有停。\n\n场景二 · 雨后的街道 · 黄昏\n\n陈序向她伸出手。他们走进同一把伞下，雨渐渐停了。\n\n陈序：这一次，一起走吧。\n林夏：好。下次，换我等你。\n\n旁白：有些重逢，是故事重新开始。`)}</textarea><div class="script-footer"><span>中文 · 都市情感 · 2 个场景</span><button class="btn small" data-action="parse-script">${icon('sparkles')} 解析为分镜</button></div></section><section class="surface-card"><div class="row between" style="margin-bottom:20px"><h3 style="margin:0">标准章节分镜</h3><span class="badge neutral">10 分格</span></div>${[{n:'01—03',name:'雨中的重逢',tag:'建立情境',desc:'街角书店远景 → 林夏特写 → 陈序回望。慢节奏运镜，用雨声连接记忆。'},{n:'04—06',name:'未寄出的信',tag:'情绪推进',desc:'信封特写 → 双人对话 → 伸手。保留沉默，让人物表情承载情绪。'},{n:'07—10',name:'雨停之后',tag:'章节钩子',desc:'共伞中景 → 城市全景 → 林夏微笑 → 两人背影。以暖光结束本章。'}].map(a=>`<div class="script-scene"><div class="row"><span class="badge neutral">${a.n}</span><strong>${a.name}</strong><span class="badge" style="margin-left:auto">${a.tag}</span></div><p>${a.desc}</p></div>`).join('')}<div class="script-footer"><span>预估时长 ${total()} 秒 · 分格数 ${state.shots.length}</span><button class="btn primary small" data-action="confirm-script">确认，设置视觉资产 ${icon('arrow')}</button></div></section></div><div class="page-note">${icon('eye')}<span>AI 解析结果需经你确认。可以修改对白、顺序与情绪节奏，确认后再批量生成图片。</span></div></div>`;}
function renderExport(){return `<div class="page-content"><div class="page-header"><div><span class="eyebrow">CHAPTER 01 / REVIEW & EXPORT</span><h1>最后一遍，把故事交给观众。</h1><p>确认采用的版本、检查异常，导出你的条漫或 Motion Comic。</p></div><div class="row"><button class="btn small" data-action="manifest">${icon('layers')} 版本清单</button><button class="btn small" data-action="report">${icon('file')} 生产报告</button></div></div><div class="export-layout"><section class="export-preview"><div class="preview-frame">${image(6)}<div class="preview-subtitle">${esc(state.shots[6].dialogue)}</div><button class="play-overlay" data-action="preview" aria-label="预览完整章节">${icon('play')}</button></div><div class="export-title">BEFORE THE RAIN ENDS</div><p class="muted" style="font-size:10px;margin-top:10px">第 01 章 · ${state.shots.length} 镜头 · ${total()} 秒</p></section><section class="export-form"><div class="surface-card"><div class="row between"><h3 style="margin:0">导出前检查</h3><span class="badge ${countReview()?'warning':'success'}">${countReview()?countReview()+' 项待确认':'全部通过'}</span></div><div class="check-list"><div class="check-line">${icon('check')} ${state.shots.length} 个镜头均有可用稳定版本</div><div class="check-line ${state.locked?'':'warning'}">${icon(state.locked?'check':'warning')} ${state.locked?'角色、场景与画风资产已锁定':'资产存在新草稿，需要重新锁定'}</div><div class="check-line">${icon('check')} 配音、字幕与镜头时长匹配</div><div class="check-line">${icon('check')} 本章费用 ${money(state.spend)}，在预算内</div><div class="check-line ${countReview()?'warning':''}">${icon(countReview()?'warning':'check')} ${countReview()?'字幕与角色一致性有待人工确认':'字幕安全区与角色一致性已确认'}${countReview()?'<button class="text-link" data-action="review-all">处理 →</button>':''}</div></div></div><div class="surface-card"><div class="export-settings"><label>导出内容<select id="export-type" aria-label="导出内容" data-export-field="type"><option value="video">Motion Comic · MP4</option><option value="png">条漫长图 · PNG</option><option value="report">生产报告 · JSON</option></select></label><label>画面规格<select aria-label="导出分辨率"><option>1080 × 1920 · 9:16</option></select></label><label>帧率<select aria-label="导出帧率" data-export-field="fps"><option value="24">24 fps</option><option value="30">30 fps</option></select></label><label>字幕<select aria-label="导出字幕" data-export-field="subtitles"><option value="zh">仅中文字幕</option><option value="bilingual">嵌入中英双语字幕</option><option value="none">不嵌入字幕</option></select></label></div><div class="export-totals"><div><strong>${total()}s</strong><small>成片时长</small></div><div><strong>${state.shots.filter(s=>s.channel==='stable').length} + ${state.shots.filter(s=>s.channel==='enhanced').length}</strong><small>稳定 / 增强镜头</small></div><div><strong>${money(state.spend)}</strong><small>模拟制作费用</small></div></div></div><label class="approval"><input type="checkbox" id="export-approve" ${state.approved?'checked':''}> 我已检查本章内容，并确认使用当前采用版本导出。</label><button class="btn primary full" data-action="start-export">${icon('export')} 确认并导出</button><p class="tiny" style="text-align:center;line-height:1.8">原型导出用于演示流程。可下载示例 PNG、生产报告及导出清单。</p></section></div></div>`;}
function renderTimeline(){const n=total();$('#timeline').innerHTML=`<div class="timeline-header"><div class="timeline-title">${icon('film')} 章节时间线 <small>视频 / 配音 / 音乐</small></div><div class="timeline-actions"><button class="icon-btn" data-action="restart-play" title="回到开头">${icon('rewind')}</button><button class="icon-btn" id="timeline-play" data-action="chapter-play" title="播放 / 暂停">${icon(playing?'pause':'play')}</button><input class="timeline-seek" type="range" min="0" max="${n}" step="0.1" value="${elapsed}" data-field="timeline-position" aria-label="章节播放位置"><span id="timeline-time">${time(elapsed)} <span style="color:#5b5067">/ ${time(n)}</span></span><span style="margin:0 3px;color:#51455f">│</span><button class="icon-btn" data-action="timeline-zoom" title="放大时间线">${icon('plus')}</button><span>100%</span><button class="icon-btn" data-action="timeline-help" title="时间线帮助">${icon('settings')}</button></div></div><div class="timeline-body"><div class="track-labels"><span>${icon('film')} 画面</span><span>${icon('music')} 音频</span></div><div class="tracks"><div class="ruler">${Array.from({length:9},(_,i)=>`<span>${time(i*n/8)}</span>`).join('')}</div><div class="video-track">${state.shots.map((s,i)=>`<button class="timeline-clip ${state.selected===i?'active':''}" data-shot="${i}" style="flex:${s.duration}" title="${esc(s.title)} · ${s.duration} 秒">${image(i)}<span>${String(i+1).padStart(2,'0')} ${esc(s.title)}</span></button>`).join('')}</div><div class="audio-track"><span>♫ Rainy afternoon · 配音已同步</span>${Array.from({length:110},(_,i)=>`<b style="height:${3+(i*17%15)}px"></b>`).join('')}</div><div class="playhead" id="playhead" style="left:${elapsed/n*100}%"></div></div></div>`;}
function selectShot(index){if(index<0||index>=state.shots.length)return;stopPlayback();state.selected=index;state.inspectorTab=state.page==='comic'?'panel':'motion';if(state.page==='comic'||state.page==='motion'){const scroll=$('.board-scroll')?.scrollTop||0;render();$('.board-scroll').scrollTop=scroll;if(innerWidth<=600)$('.inspector')?.classList.add('mobile-open');}else navigate('motion');save();}
function openModal(title,body,footer='',wide=false){stopPlayback();if(modalTimer){clearInterval(modalTimer);modalTimer=null;}modalReturnFocus=document.activeElement;$('#modal-layer').hidden=false;$('#modal-layer').innerHTML=`<section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modal-header"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section>`;setTimeout(()=>$('.modal input:not([type=checkbox]),.modal textarea,.modal-footer .primary,.modal-header button')?.focus(),50);}
function closeModal(){if(modalTimer){clearInterval(modalTimer);modalTimer=null;}$('#modal-layer').hidden=true;$('#modal-layer').innerHTML='';if(modalReturnFocus?.isConnected)modalReturnFocus.focus();modalReturnFocus=null;}
const cancelBtn='<button class="btn subtle" data-action="close-modal">取消</button>';
function enhancementModal(){const s=shot();openModal('让关键动作，更进一步。',`<div class="modal-shot-preview">${image(state.selected)}<div><strong>镜头 ${String(state.selected+1).padStart(2,'0')} · ${esc(s.title)}</strong><span>基于当前分格 v${s.version} · 稳定动画将始终保留</span><div><span class="badge success">稳定底稿已就绪</span></div></div></div><label class="modal-label" for="enhance-prompt">动作描述 <small>保持角色、画风与构图</small></label><textarea id="enhance-prompt" placeholder="描述希望增加的动作…">${state.selected===5?'陈序缓慢向前伸出右手，衣袖随动作轻微摆动，保持面部与背景不变。':'角色缓慢抬头，眼神变得温柔，镜头轻轻推进。保持角色身份、服装和原作信息不变。'}</textarea><div class="row" style="gap:14px"><div style="flex:1"><label class="modal-label">视频模型</label><select id="enhance-model" aria-label="视频模型"><option>Kling 3.0 Standard</option></select></div><div style="width:110px"><label class="modal-label">候选数量</label><select id="enhance-count" aria-label="候选数量"><option value="1">1 个候选</option><option value="2">2 个候选</option></select></div></div><div class="cost-summary"><div class="row between"><span>本次预计费用</span><strong id="estimate-cost">$0.45</strong></div><div class="row between"><span>预计时延</span><span>2–4 分钟</span></div><div class="row between"><span>调用后本章预估</span><span id="estimate-total">${money(state.spend+.45)} / ${money(state.budget)}</span></div></div><p class="cost-note">演示模式：点击确认仅模拟生成过程，不调用模型、不产生实际费用。候选由你确认采用，生成失败可回退稳定版。</p>`,`${cancelBtn}<button class="btn primary" data-action="confirm-enhance">${icon('sparkles')} 确认费用并生成</button>`);}
function simulate(title,steps,onComplete){let progress=0;openModal(title,`<div class="progress-wrap"><div class="progress-orbit"></div><h3 id="progress-heading">${steps[0]}</h3><p style="margin-top:10px">演示流程 · 无真实 API 调用</p><div class="progress-line"><b id="progress-bar"></b></div><small class="muted" id="progress-percent">0%</small></div>`,'');modalTimer=setInterval(()=>{progress=Math.min(100,progress+12+Math.floor(Math.random()*9));if($('#progress-bar'))$('#progress-bar').style.width=progress+'%';if($('#progress-percent'))$('#progress-percent').textContent=progress+'%';if($('#progress-heading'))$('#progress-heading').textContent=steps[Math.min(steps.length-1,Math.floor(progress/100*steps.length))];if(progress===100){clearInterval(modalTimer);modalTimer=null;setTimeout(()=>{if(!$('#modal-layer').hidden)onComplete();},350);}},240);}
function confirmEnhance(){
 const count=Number($('#enhance-count').value),cost=count*.45;
 if(!$('#enhance-prompt').value.trim()){toast('请填写动作描述。','warning');return;}
 if(state.spend+cost>state.budget){toast('超过本章预算，已阻止新的付费生成。稳定动画仍可导出。','warning');return;}
 if(state.spend+cost>=state.budget*.8)toast('预计累计费用达到预算的 80%，请留意剩余重试额度。','warning');
 const i=state.selected;
 simulate('正在生成增强候选',['提交参考资产','保持角色与画风','生成关键动作','候选质量检查'],()=>{
  state.spend=Number((state.spend+cost).toFixed(2));state.shots[i].hasEnhanced=true;state.shots[i].enhancedCount=count;
  log('增强候选已生成',`镜头 ${i+1} · ${count} 个候选 · 演示费用 ${money(cost)}`);
  const candidates=Array.from({length:count},(_,j)=>`<div class="result-candidate">${image(i)}<div><h3>✧ 增强候选 ${String.fromCharCode(65+j)}</h3><p>Kling 3.0 · 5 秒 · ${j?'动作更克制':'动作更明显'}</p><button class="btn primary full small" data-action="adopt-enhanced" data-candidate="${j+1}">${count===1?'采用增强候选':'采用候选 '+String.fromCharCode(65+j)}</button></div></div>`).join('');
  openModal('候选已就绪，由你决定。',`<p>对比稳定版与 ${count} 个增强候选。候选未采用前，当前版本继续保留。</p><div class="result-grid" style="${count===2?'grid-template-columns:repeat(3,1fr)':''}"><div class="result-candidate">${image(i)}<div><h3>稳定版 v${state.shots[i].version}</h3><p>确定性运镜 · 保留原作信息</p><button class="btn subtle full small" data-action="keep-stable">继续使用稳定版</button></div></div>${candidates}</div><p class="cost-note">原型候选以同一张本地插画表示，仅演示对比、采用与回退关系。</p>`,`<button class="btn subtle" data-action="close-modal">稍后决定</button><button class="btn" data-action="simulate-failure">演示失败回退</button>`,count===2);
  render();
 });
}
function editShotModal(panel=false){const s=shot();openModal(panel?'分格编辑 · 只改你想改的部分':'单镜头编辑 · 每一处细节都可控',`<div class="edit-layout"><div class="edit-picture">${image(state.selected)}${panel?'<div class="mask"></div>':''}<small>${panel?'选区示意 · 修改前始终保留旧版本':'9:16 安全裁切 · 稳定版本 v'+s.version}</small></div><div class="edit-form"><div class="row"><span class="badge">${s.speaker==='旁白'?'双人场景':esc(s.speaker)}</span><span class="badge neutral">雨日手绘 v1</span></div><label>标题<input id="edit-title" value="${esc(s.title)}" maxlength="32"></label><label>对白<textarea id="edit-dialogue">${esc(s.dialogue)}</textarea></label>${panel?`<label>局部修改指令<textarea id="edit-prompt" placeholder="例如：让角色微笑，保留其余画面不变">让林夏的表情更柔和，轻微微笑。保持角色身份、服装与背景不变。</textarea></label><label>姿势 / 表情<select id="edit-expression"><option>自然站姿 · 微笑</option><option>低头看信 · 平静</option><option>抬头回望 · 惊讶</option></select></label>`:`<label>运镜模板<select id="edit-template">${['固定镜头','横向摇移','缓慢推进','缓慢拉远','视差景深'].map(t=>`<option ${s.template===t?'selected':''}>${t}</option>`).join('')}</select></label><label>镜头时长（秒）<input id="edit-duration" type="number" min="2" max="10" step="1" value="${s.duration}" style="width:100%"></label><div class="switch-row">口型同步<button class="switch ${shot().settings.lipsync?'on':''}" data-toggle="lipsync" role="switch" aria-label="编辑器口型同步" aria-checked="${shot().settings.lipsync}"></button></div>`}</div></div>`,`${cancelBtn}<button class="btn primary" data-action="${panel?'save-panel-edit':'save-shot-edit'}">${icon(panel?'sparkles':'check')} ${panel?'生成局部修改候选 · $0.08':'应用到章节'}</button>`,true);}
function saveEdit(panel=false){const s=shot();const title=$('#edit-title').value.trim(),dialogue=$('#edit-dialogue').value.trim();if(!title||!dialogue){toast('请填写镜头标题与对白。','warning');return;}if(panel){if(state.spend+.08>state.budget){toast('预算不足，已停止新生成。','warning');return;}const id=state.selected;simulate('正在局部修改',['读取选区与资产版本','仅调整选区内表情','保留角色、服装与背景','新候选已生成'],()=>{openModal('分格候选已生成',`<div class="compare-grid"><div><h3>当前版本 v${s.version}</h3>${image(id)}</div><div><h3>新候选 v${s.version+1}</h3>${image(id)}<p style="margin-top:10px;font-size:10px">表情调整 · 背景与服装保持不变</p></div></div><div class="notice" style="margin:20px 0 0">${icon('layers')}采用后只更新这个分格，并将对应镜头标记为待同步。已有动画继续保留。</div>`,`${cancelBtn}<button class="btn primary" data-action="adopt-panel" data-title="${esc(title)}" data-dialogue="${esc(dialogue)}">采用新分格版本</button>`,true);state.spend=+(state.spend+.08).toFixed(2);save();});return;}const duration=Number($('#edit-duration').value);if(!Number.isFinite(duration)||duration<2||duration>10){toast('镜头时长需在 2–10 秒之间。','warning');return;}const plannedTotal=total()-s.duration+duration;if(plannedTotal<30||plannedTotal>60){toast('章节总长需保持在 30–60 秒之间。','warning');return;}rememberRevision(s,'镜头编辑前');Object.assign(s,{title,dialogue,duration,template:$('#edit-template').value});state.approved=false;s.version++;log('镜头参数已更新',`镜头 ${state.selected+1} · 仅重做当前镜头`);closeModal();render();toast('已应用到章节，仅更新当前镜头。');}
function reviewModal(all=false){
 const list=all?state.shots.map((s,i)=>({s,i})).filter(a=>a.s.review):[{s:shot(),i:state.selected}];
 openModal('逐项确认，让交付更放心。',`<p style="margin-bottom:18px">问题只影响对应镜头。你可以修正后重新预览，或确认当前结果可以接受。</p>${list.map(({s,i})=>{
 const subtitle=s.reviewType==='subtitle',sync=s.reviewType==='sync';
 return `<div class="review-card"><div class="row" style="justify-content:flex-start;gap:10px;margin-bottom:10px">${image(i).replace('<img','<img style="width:75px;height:50px;border-radius:4px"')}<div><h3>镜头 ${i+1} · ${esc(s.title)}</h3><span class="badge warning">${subtitle?'字幕靠近下方安全区':sync?'分格新版本待同步':'角色表情一致性需确认'}</span></div></div><p>${subtitle?'建议将字幕上移 24 px，避免平台底部控件遮挡。':sync?'当前动画保留了旧底稿。确认后将演示将新分格同步至当前稳定镜头。':'本镜头笑容比资产参考更明显。请确认是剧情需要，或回到分格进行局部编辑。'}</p><div class="row"><button class="btn small subtle" data-action="jump-edit" data-index="${i}">局部编辑</button><button class="btn small primary" data-action="resolve-review" data-index="${i}">${subtitle?'上移字幕并确认':sync?'同步当前镜头并确认':'确认当前表情'}</button></div></div>`;
 }).join('')}`,`<button class="btn" data-action="close-modal">完成审查</button>`);
}
function exportStart(){
 const kind=$('#export-type')?.value||'video';
 if(kind==='report'){downloadReport();return;}
 if(!state.locked){toast('资产存在未确认变更，请先重新锁定。','warning');return;}
 if(countReview()){reviewModal(true);return;}
 if(!$('#export-approve')?.checked){toast('请先勾选最终内容确认。','warning');return;}
 if(kind==='png'){exportPNG();return;}
 state.approved=true;log('最终审批已通过','当前采用版本已冻结');
 simulate('正在合成章节',['冻结采用版本清单','合成镜头、字幕与配音','检查画面规格与音画同步','生成生产报告'],()=>{
  log('章节导出流程已完成',`${total()} 秒 · 1080×1920 · 原型模拟`);
  window.dispatchEvent(new CustomEvent('framein:download',{detail:{name:'章节视频 · 合成流程演示',kind:'MP4',size:0}}));
  openModal('你的故事，准备好了。',`<div style="text-align:center"><div class="success-symbol">✓</div><h2 style="font-size:20px">《${esc(studioProject?.name||'雨停之前')}》· ${esc(studioChapter?.title||'第 01 章')}</h2><p style="margin-top:9px">${state.shots.length} 个镜头 · ${total()} 秒 · ${money(state.spend)} 制作费用</p></div><div class="export-success-file">${icon('film')}<div><strong>${esc(studioProject?.name||'雨停之前')}_${esc(studioChapter?.title||'第 01 章')}.mp4</strong><small>1080×1920 · ${state.exportOptions.fps} fps · H.264 / AAC · 导出流程演示完成</small></div><span class="badge success" style="margin-left:auto">模拟完成</span></div><p class="cost-note">静态原型不生成真实 MP4。可下载本次采用版本清单和生产报告，或下载示例条漫 PNG。</p>`,`<button class="btn" data-action="download-manifest">${icon('download')} 下载版本清单</button><button class="btn primary" data-action="download-report">${icon('file')} 下载生产报告</button>`);
 });
}
function report(){return {prototype:true,project:studioProject?.name||'雨停之前',chapter:studioChapter?.title||'重逢的第七天',generatedAt:new Date().toISOString(),resolution:'1080x1920',durationSeconds:total(),exportSettings:{width:1080,height:1920,...state.exportOptions},assets:{characters:['林夏 v2','陈序 v1'],scenes:['慢日子书店 v1','雨后的街道 v1'],style:'雨日手绘 v1'},cost:{simulatedUsd:state.spend,budgetUsd:state.budget},metrics:{comicActiveMinutes:34,motionActiveMinutes:16,panelLocallyEditableRate:.8,publishableRate:.8,notice:'原型示例数据，不是真实实验结果'},shots:state.shots.map((s,i)=>({index:i+1,...s})),events:state.events};}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);window.dispatchEvent(new CustomEvent('framein:download',{detail:{name,kind:name.endsWith('.png')?'PNG':'JSON',size:blob.size}}));}
function downloadReport(){downloadBlob(new Blob([JSON.stringify({...report(),project:studioProject?.name||'雨停之前',chapter:studioChapter?.title||'重逢的第七天'},null,2)],{type:'application/json;charset=utf-8'}),'framein-m0-production-report.json');toast('已下载生产报告（原型示例数据）。');}
function manifest(){return {prototype:true,project:studioProject?.name||'雨停之前',chapter:studioChapter?.title||'重逢的第七天',exportSettings:{width:1080,height:1920,...state.exportOptions},adoptedVersions:state.shots.map((s,i)=>({shotId:i+1,artIndex:s.artIndex,panelVersion:s.version,channel:s.channel,candidate:s.channel==='enhanced'?(s.adoptedCandidate||1):null,duration:s.duration,template:s.template,dialogue:s.dialogue,subtitle:s.subtitle,settings:s.settings})),approved:state.approved};}
function downloadManifest(){downloadBlob(new Blob([JSON.stringify({...manifest(),project:studioProject?.name||'雨停之前',chapter:studioChapter?.title||'重逢的第七天'},null,2)],{type:'application/json'}),'framein-ch01-version-manifest.json');toast('已下载采用版本清单。');}
function previewManifest(){openModal('本次导出版本清单',`<p>核对输出设置与采用版本。清单会跟随你的镜头编辑和导出选项更新。</p><pre class="manifest-preview">${esc(JSON.stringify(manifest(),null,2))}</pre>`,`<button class="btn" data-action="close-modal">返回</button><button class="btn primary" data-action="download-manifest">${icon('download')} 下载 JSON</button>`,true);}
async function exportPNG(){
 const button=$('[data-action="export-png"]');
 if(button){button.disabled=true;button.textContent='正在合成 PNG…';}
 toast('正在合成本地示例条漫 PNG…','clock');
 try{
  const width=state.comicWidth||1080,scale=width/1080,panelH=width*.75,gap=Math.round((state.comicGap??16)*width/310),header=220*scale;
  const canvas=document.createElement('canvas');canvas.width=width;canvas.height=header+state.shots.length*(panelH+gap+55*scale)+100*scale;
  const ctx=canvas.getContext('2d');ctx.fillStyle='#ede8dc';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#45434b';ctx.font=`bold ${54*scale}px serif`;ctx.textAlign='center';ctx.fillText(studioProject?.name||'雨停之前',width/2,100*scale,width-60*scale);ctx.font=`${22*scale}px sans-serif`;ctx.fillText(studioChapter?.title||'第 01 章 · 重逢的第七天',width/2,155*scale,width-60*scale);
  for(let i=0;i<state.shots.length;i++){const img=new Image();img.src=artForShot(i);await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(new Error('图片载入超时')),8000);img.decode().then(()=>{clearTimeout(timeout);resolve();},error=>{clearTimeout(timeout);reject(error);});});const y=header+i*(panelH+gap+55*scale);ctx.drawImage(img,0,y,width,panelH);ctx.fillStyle='#4a424e';ctx.font=`${21*scale}px sans-serif`;ctx.fillText(state.shots[i].dialogue,width/2,y+panelH+32*scale,width-60*scale);}
  canvas.toBlob(blob=>{if(blob){downloadBlob(blob,'before-the-rain-ends-ch01-demo.png');if(button){button.disabled=false;button.textContent='再次下载 PNG';button.title=`已合成 ${canvas.width} × ${canvas.height} px`; }toast('示例长图 PNG 已导出。');}else{if(button){button.disabled=false;button.textContent='重试导出 PNG';}toast('图片导出失败，请重试。','warning');}},'image/png');
 }catch(err){if(button){button.disabled=false;button.textContent='重试导出 PNG';}toast('PNG 合成未完成，请重试或下载生产报告。','warning');console.error(err);}
}
function openReport(){openModal('每一步，都有迹可循。',`<div class="time-stats"><div><strong>34 min</strong><small>条漫人工操作</small></div><div><strong>16 min</strong><small>动态漫增量操作</small></div><div><strong>${money(state.spend)}</strong><small>模拟外部模型费用</small></div></div><p style="font-size:10px;margin-bottom:17px">以下均为演示数据。正式验证时记录每次人工辅助、候选重试和模型回执。</p><div class="activity-list">${state.events.slice(-8).reverse().map(e=>`<div class="activity"><small>${esc(e.time)}</small><div><strong>${esc(e.title)}</strong><p>${esc(e.detail)}</p></div></div>`).join('')}</div>`,`<button class="btn" data-action="close-modal">关闭</button><button class="btn primary" data-action="download-report">${icon('download')} 下载报告 JSON</button>`);}
function guide(){openModal('欢迎来到Cimora。',`<div class="brand-text">CIMORA <small>故事，在每一帧之间生长。</small></div><p style="margin-top:20px">这是一个可交互的 M0 工作台原型。用一章 10 格示例故事，体验从条漫到动态漫的创作流程。</p><div class="guide-steps">${[['故事与资产','顶部步骤可以返回剧本和视觉资产，查看角色、场景与画风。'],['分格与长图','在条漫页面编辑分格、对比版本；切换长图可调整间距并导出 PNG。'],['镜头与动画','点击任意镜头卡，调整运镜、字幕与效果；底部时间线可播放示意动画。'],['增强与回退','生成增强前确认预计费用，再选择采用候选或继续使用稳定版。'],['审批与导出','处理两个待确认问题，勾选最终审批，完成导出流程并下载生产报告。']].map(([t,d],i)=>`<div class="guide-step"><b>${i+1}</b><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div><div class="shortcuts"><span><kbd>Space</kbd> 播放 / 暂停</span><span><kbd>← →</kbd> 切换镜头</span><span><kbd>Esc</kbd> 关闭弹窗</span></div>`,`<button class="btn subtle" data-action="reset-demo">重置演示</button><button class="btn primary" data-action="close-modal">开始创作 ${icon('arrow')}</button>`);}
function assetDetail(name,img){openModal(name+' · 资产设定',`${image(img,'asset-detail-img',name)}<div class="modal-label">视觉与版本约束 <span class="badge success">当前版本已锁定</span></div><p>${name==='林夏'?'深色长发、灰绿色瞳孔、红色围巾与米色风衣。表情自然克制，角色身份与服装在本章保持一致。':name==='陈序'?'棕色短发、灰蓝色外套。沉静、温柔；所有分格使用相同外貌与声音资产。':name==='雨日手绘'?'低饱和灰蓝与暖琥珀色，柔和水彩、手绘线条和细颗粒。避免写实摄影、高饱和荧光色和明显 3D 质感。':'环境、光照、空间布局与配色在同一场景内保持一致。室内外镜头共享相同场景资产版本。'}</p><div class="cost-summary"><div class="row between"><span>影响范围</span><span>${name==='雨日手绘'?'10':name==='林夏'?'6':'5'} 个分格及其动态镜头</span></div><div class="row between"><span>修改方式</span><span>创建新版本 · 保留原有画面</span></div></div>`,`<button class="btn" data-action="close-modal">关闭</button><button class="btn primary" data-action="asset-new-version" data-name="${esc(name)}">创建新版本</button>`);}
function projects(){openModal('你的故事工作空间',`<div class="project-gallery"><button class="project-tile" data-action="open-current">${image(6)}<div><strong>雨停之前</strong><small>1 章节 · 10 分格 · 48 秒</small></div></button><button class="project-tile new-project" data-action="create-project">${icon('plus')}<span>创建新项目</span><small>从完整剧本开始</small></button></div><p class="local-note">所有更改只保存于当前浏览器，可随时重置演示。</p>`);}
function seekTime(value){
 stopPlayback();elapsed=Math.max(0,Math.min(total(),value));let sum=0,index=state.shots.length-1;
 for(let i=0;i<state.shots.length;i++){sum+=state.shots[i].duration;if(elapsed<sum){index=i;break;}}
 if(index!==state.selected){state.selected=index;const current=$('.inspector');if(current){const mobile=current.classList.contains('mobile-open');current.outerHTML=renderInspector(state.page==='comic');if(mobile)$('.inspector').classList.add('mobile-open');syncPreview();}$$('[data-shot]').forEach(c=>{c.classList.toggle(c.classList.contains('shot-card')?'selected':'active',Number(c.dataset.shot)===index);if(c.hasAttribute('aria-pressed'))c.setAttribute('aria-pressed',Number(c.dataset.shot)===index);});}
 const start=state.shots.slice(0,index).reduce((n,s)=>n+s.duration,0),progress=$('#preview-progress');if(progress)progress.value=elapsed-start;
 if($('#timeline-time'))$('#timeline-time').innerHTML=`${time(elapsed)} <span style="color:#5b5067">/ ${time(total())}</span>`;
 if($('#playhead'))$('#playhead').style.left=(elapsed/total()*100)+'%';
 const seek=$('[data-field="timeline-position"]');if(seek)seek.value=elapsed;
}
function stopPlayback(){playing=false;if(playTimer)clearInterval(playTimer);playTimer=null;$('#inspector-preview')?.classList.remove('playing');$('#timeline-play')?.replaceChildren();if($('#timeline-play'))$('#timeline-play').innerHTML=icon('play');$$('.play-overlay').forEach(b=>{if(b.dataset.action==='toggle-play')b.innerHTML=icon('play');});}
function startPlayback(chapter=false){
 if(playing){stopPlayback();return;}
 playing=true;const start=state.shots.slice(0,state.selected).reduce((n,s)=>n+s.duration,0),end=start+shot().duration;
 if(!chapter)elapsed=start;else if(elapsed>=total())elapsed=0;
 const refreshInspector=()=>{const current=$('.inspector');if(current){const mobile=current.classList.contains('mobile-open');current.outerHTML=renderInspector(state.page==='comic');if(mobile)$('.inspector').classList.add('mobile-open');syncPreview();}$('#inspector-preview')?.classList.add('playing');$$('[data-action="toggle-play"]').forEach(b=>b.innerHTML=icon('pause'));};
 refreshInspector();if($('#timeline-play'))$('#timeline-play').innerHTML=icon('pause');
 playTimer=setInterval(()=>{
  elapsed=Math.min(elapsed+.1,chapter?total():end);
  let sum=0,idx=state.shots.length-1;
  for(let i=0;i<state.shots.length;i++){sum+=state.shots[i].duration;if(elapsed<sum-.001){idx=i;break;}}
  if(chapter&&idx!==state.selected){state.selected=idx;$$('.shot-card[data-shot],.timeline-clip[data-shot]').forEach(c=>c.classList.toggle(c.classList.contains('shot-card')?'selected':'active',Number(c.dataset.shot)===idx));refreshInspector();}
  if($('#playhead'))$('#playhead').style.left=(elapsed/total()*100)+'%';
  const seek=$('[data-field="timeline-position"]');if(seek)seek.value=elapsed;
  if($('#timeline-time'))$('#timeline-time').innerHTML=`${time(elapsed)} <span style="color:#5b5067">/ ${time(total())}</span>`;
  const pp=$('#preview-progress');if(pp)pp.value=Math.min(shot().duration,elapsed-state.shots.slice(0,state.selected).reduce((n,s)=>n+s.duration,0));
  if(elapsed>=(chapter?total():end)-.001)stopPlayback();
 },100);
}
function fullPreview(){openModal('章节预览 · '+(studioProject?.name||'雨停之前'),`<div class="preview-modal-stage"><span class="full-preview-name">${esc(studioChapter?.title||'第 01 章 · 重逢的第七天')}</span><div class="preview-frame playing" id="full-preview-frame">${image(0)}<div class="preview-subtitle">${esc(state.shots[0].dialogue)}</div></div></div><div class="preview-time"><button class="icon-btn" data-action="full-preview-play" aria-label="暂停章节预览">${icon('pause')}</button><span id="full-preview-time">00:00</span><input type="range" aria-label="章节预览进度" min="0" max="${total()}" value="0" id="full-preview-range"><span>${time(total())}</span></div><p class="local-note">运镜与镜头切换示意 · 配音及视频生成未接入</p>`,'',true);let t=0;modalTimer=setInterval(()=>{if($('#full-preview-frame')?.dataset.paused==='true')return;t=Number($('#full-preview-range')?.value||t)+.2;if(t>total())t=0;const range=$('#full-preview-range');if(range)range.value=t;updateFullPreview(t);},200);}
function updateFullPreview(t){let cumulative=0,index=state.shots.length-1;for(let i=0;i<state.shots.length;i++){cumulative+=state.shots[i].duration;if(t<cumulative){index=i;break;}}const frame=$('#full-preview-frame');if(frame){frame.dataset.motion=state.shots[index].template;frame.style.setProperty('--motion-strength',String(1+shot().settings.intensity/180));}if($('#full-preview-frame img'))$('#full-preview-frame img').src=artForShot(index);if($('#full-preview-frame .preview-subtitle'))$('#full-preview-frame .preview-subtitle').textContent=state.shots[index].dialogue;if($('#full-preview-time'))$('#full-preview-time').textContent=time(t);}
function speech(name){if(!('speechSynthesis' in window)){toast('此浏览器不支持示例语音预览。','warning');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(name==='陈序'?'这一次，一起走吧。':'七年了，你还记得我吗？');u.lang='zh-CN';u.rate=.86;u.pitch=name==='陈序'?.75:1.15;speechSynthesis.speak(u);toast('正在用浏览器语音示意试听，非 ElevenLabs 真实音色。','voice');}

function rememberRevision(s,label){
 const fields=['title','dialogue','speaker','duration','template','settings','subtitle','channel','review','reviewType','subtitleLift','artIndex'];
 const snapshot=Object.fromEntries(fields.map(key=>[key,structuredClone(s[key])]));
 s.revisions??=[];s.revisions.unshift({version:s.version,label,at:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),snapshot});s.revisions=s.revisions.slice(0,6);
}
function renderVersions(){
 const s=shot();return `<div class="property-label">当前采用 <small>稳定底稿始终保留</small></div><div class="versions"><div class="version-row ${s.channel==='stable'?'adopted':''}">${image(state.selected)}<span><strong>稳定版 v${s.version}</strong><small>${esc(s.template)} · ${s.duration} 秒</small></span><button class="btn small" data-action="adopt-stable" ${s.channel==='stable'?'disabled':''}>${s.channel==='stable'?'已采用':'采用'}</button></div>${s.hasEnhanced?`<div class="version-row ${s.channel==='enhanced'?'adopted':''}">${image(state.selected)}<span><strong>增强候选 ${String.fromCharCode(64+(s.adoptedCandidate||1))}</strong><small>与稳定底稿独立保留</small></span><button class="btn small" data-action="adopt-enhanced" ${s.channel==='enhanced'?'disabled':''}>${s.channel==='enhanced'?'已采用':'采用'}</button></div>`:''}</div><div class="property-label">参数历史 <small>最近 6 次 · 可恢复</small></div><div class="revision-list">${s.revisions.length?s.revisions.map(r=>`<button class="revision-card" data-action="review-revision" data-version="${r.version}"><span class="revision-symbol">v${r.version}</span><span><strong>${esc(r.label)}</strong><small>${esc(r.snapshot.template)} · ${r.snapshot.duration} 秒 · ${r.at}</small></span>${icon('history')}</button>`).join(''):'<div class="revision-empty">编辑当前镜头后，会在这里保留修改前的参数快照。</div>'}</div><button class="btn subtle full small" data-action="enhance">${icon('plus')} 生成增强候选</button><p class="tiny">参数恢复会创建新版本，已有候选和历史继续保留。</p>`;
}
function revisionModal(version){
 const s=shot(),r=s.revisions.find(v=>v.version===Number(version));if(!r)return;
 const column=(label,data)=>`<div class="revision-compare"><h3>${label}</h3>${image(state.selected)}<dl><dt>标题</dt><dd>${esc(data.title)}</dd><dt>运镜</dt><dd>${esc(data.template)}</dd><dt>时长</dt><dd>${data.duration} 秒</dd><dt>对白</dt><dd>${esc(data.dialogue)}</dd></dl></div>`;
 openModal('恢复参数，保留每一步。',`<p>将历史 v${r.version} 的参数恢复为新版本。当前 v${s.version} 会先保存为快照，不产生额外模型费用。</p><div class="compare-grid">${column('历史 v'+r.version,r.snapshot)}${column('当前 v'+s.version,s)}</div>`,`${cancelBtn}<button class="btn primary" data-action="restore-revision" data-version="${r.version}">${icon('undo')} 恢复为新版本</button>`,true);
}
function restoreRevision(version){
 const s=shot(),r=s.revisions.find(v=>v.version===Number(version));if(!r)return;
 const restored=structuredClone(r.snapshot),nextVersion=s.version+1,plannedTotal=total()-s.duration+restored.duration;
 if(plannedTotal<30||plannedTotal>60){toast('恢复后章节时长将超出 30–60 秒，请先调整其他镜头。','warning');return;}
 rememberRevision(s,'恢复前的版本');Object.assign(s,restored);s.version=nextVersion;state.approved=false;
 log('镜头参数已恢复',`镜头 ${state.selected+1} · 从 v${version} 恢复为 v${nextVersion}`);closeModal();render();toast('已恢复历史参数，修改前的版本也已保留。');
}

